def list_dir(d, max_depth=5, prefix=''):
    results = []
    try:
        items = list(d.iterdir())
    except:
        return results
    for item in items:
        if item.is_file():
            results.append(f"{prefix} {item.name}")
        elif item.is_dir():
            try:
                subitems = list_dir(item, max_depth-1, prefix + '  ')
                results.extend(subitems)
            except:
                results.append(f"{prefix} {item.name}/")
    return results

